 const assets=await js<{scene:{url:string;loaded:boolean;width:number;height:number};sprite:{url:string;loaded:boolean;width:number;height:number};props:Array<{name:string;visible:boolean;position:string;rect:{left:number;top:number;right:number;bottom:number};inside:boolean}>;sceneRect:{left:number;top:number;right:number;bottom:number};level:string}>(win,`(async()=>{const scene=document.getElementById('lifeScene'),r=scene.getBoundingClientRect(),bg=getComputedStyle(scene).backgroundImage,url=bg.match(/url\\(["']?(.*?)["']?\\)/)?.[1]||'',im=new Image();im.src=url;try{await im.decode()}catch{}const props=[...scene.querySelectorAll('.life-prop')].map(e=>{const q=e.getBoundingClientRect(),style=getComputedStyle(e);return{name:e.dataset.prop,visible:style.display!=='none'&&q.width>0,position:style.backgroundPosition,rect:{left:q.left,top:q.top,right:q.right,bottom:q.bottom},inside:q.width===0||q.left>=r.left&&q.right<=r.right&&q.top>=r.top&&q.bottom<=r.bottom}});const spriteStyle=getComputedStyle(scene.querySelector('.life-prop[data-prop=crate]')),spriteUrl=spriteStyle.backgroundImage.match(/url\\(["']?(.*?)["']?\\)/)?.[1]||'',sprite=new Image();sprite.src=spriteUrl;try{await sprite.decode()}catch{}return{scene:{url,loaded:im.naturalWidth>0,width:im.naturalWidth,height:im.naturalHeight},sprite:{url:spriteUrl,loaded:sprite.naturalWidth>0,width:sprite.naturalWidth,height:sprite.naturalHeight},props,sceneRect:{left:r.left,top:r.top,right:r.right,bottom:r.bottom},level:scene.dataset.level}})()`);
 assert.ok(assets.scene.loaded&&assets.scene.width>0&&assets.scene.height>0,`camp background asset failed: ${JSON.stringify(assets.scene)}`);assert.ok(assets.sprite.loaded&&assets.sprite.width>0&&assets.sprite.height>0,`0x72 sprite sheet failed: ${JSON.stringify(assets.sprite)}`);assert.ok(assets.props.some(p=>p.visible),'rich level should visibly place furnishings');assert.ok(assets.props.every(p=>p.inside),`furnishing outside landscape bounds: ${JSON.stringify(assets.props)}`);assert.ok(assets.props.filter(p=>p.visible).every(p=>p.position!=='0px 0px'),`furnishing CSS position missing: ${JSON.stringify(assets.props)}`);check('static growth landscape pixels and 0x72 furniture positions verified',assets);
