 const buddies=Object.keys((awaitlessCompanions())) as Companion[];p.leisure.companions=Object.fromEntries(buddies.map(id=>[id,14])) as Profile['leisure']['companions'];p.leisure.active='slime';p.leisure.cooked=60;p.leisure.harvests=20;p.leisure.gardenLevel=2;p.leisure.journal.buildings={lodge:3,workshop:3,archive:3};p.leisure.journal.dust=1_000;
 const bonds=initialBonds();for(const id of BUDDY_ORDER)bonds.progress[id]={path:null,rank:0,voyages:20,stories:0};bonds.support='guide';bonds.secretClears=[3,3,3,3,3];p.leisure.bonds=bonds;
 p.business.managed=true;p.business.till=123;p.business.shelves.ration={stock:1,tier:'normal',due:p.tick+1};p.retail=true;
 const a=initialAtelier();a.till=234;a.facilities={kitchen:3,still:3,counter:3};for(const good of Object.keys(FORMULAS) as (keyof typeof FORMULAS)[]){a.stock[good]=200;a.made[good]=good==='ink'?20:0;}a.shelves.picnic.stock=atelierShelfLimit(a);for(const station of ['supply','alchemy'] as const)for(const order of a.orders[station])order.revision=2;p.atelier=a;
