function writeProfileFixture(value:unknown,label:string):string{
 const checked=parseProfile(value);const dir=path.join(profileRoot,'import-fixtures');fs.mkdirSync(dir,{recursive:true,mode:0o700});const file=path.join(dir,label);fs.writeFileSync(file,JSON.stringify(checked)+'\n',{flag:'wx',mode:0o600});assert.deepEqual(parseProfile(JSON.parse(fs.readFileSync(file,'utf8'))),checked,`${label} profile fixture parse preflight`);fixtureFiles.push(file);return file;
}
function queuePicker(pathname:string,canceled=false,deferred=false):void{assert.ok(path.resolve(pathname).startsWith(profileRoot+path.sep),`picker path escapes this isolated root: ${pathname}`);mockDialog.queue.push({path:pathname,canceled,deferred});}
async function waitPickerCall(previous:number):Promise<void>{await until(()=>mockDialog.calls.length>previous,'mock dialog invoked');}
function gameGeneration(win:BrowserWindowType):Promise<number>{return js(win,`Number(document.body.dataset.generation)`);}
async function clickImportPick(win:BrowserWindowType,expectError?:RegExp):Promise<void>{
 const before=mockDialog.calls.length;await clickElement(win,'gameImportPick');
 if(expectError){await until(()=>js<boolean>(win,`new RegExp(${JSON.stringify(expectError.source)}).test(document.getElementById('popupError')?.textContent||'')`),`import error ${expectError}`);check('settings import rejected with expected user-facing error',{expected:String(expectError),actual:await js(win,`document.getElementById('popupError')?.textContent||''`)});}
 else await waitPickerCall(before);
}
async function waitPreview(win:BrowserWindowType,previousTokenCount:number):Promise<void>{await until(()=>mockDialog.previews.length>previousTokenCount&&js<boolean>(win,`!!document.getElementById('gameImportPreview')?.textContent&&document.getElementById('popupError')?.textContent===''`),'new main-IPC import preview result rendered');}
async function getLastPreviewToken():Promise<string>{const last=mockDialog.previews.at(-1);assert.ok(last?.token,'main IPC wrapper did not observe import token');return last.token;}
async function readErrorsAndKeyboard():Promise<void>{
 const skipped:number[]=[];for(const win of BrowserWindow.getAllWindows()){track(win);if(win.isDestroyed()||win.webContents.isDestroyed()||!page(win)){skipped.push(win.id);continue;}try{await instrument(win);const v=await js<{keys:number;csp:unknown[]}>(win,'({keys:window.__camp090KeyEvents||0,csp:window.__camp090Csp||[]})');keyboardByWindow[win.id]=v.keys;cspByWindow[win.id]=[...(cspByWindow[win.id]??[]),...v.csp.map(String)];}catch(e){if(!win.isDestroyed()&&!win.webContents.isDestroyed())throw e;skipped.push(win.id);}}
 assert.equal(Object.values(keyboardByWindow).reduce((n,v)=>n+v,0),0,'keyboard event observed');assert.equal(Object.values(cspByWindow).reduce((n,v)=>n+v.length,0),0,'CSP violation observed');check('zero renderer keyboard events and zero CSP violations',{keyboardByWindow,cspByWindow,skipped});
}

