 assert.equal(campOf(profile()).cooking.length,3);await disabled(win,'lifeCook1',/最多三批/);await disabled(win,'lifeCook5',/最多三批/);
 const queueBefore=structuredClone(campOf(profile()).cooking),resourcesBefore={herb:profile().leisure.materials.herb,pumpkin:profile().leisure.materials.pumpkin,snowflower:profile().leisure.materials.snowflower,flour:profile().bag.flour};for(const pos of [2,1,0])await actionClick(win,`lifeCancelFood${pos}`);assert.equal(campOf(profile()).cooking.length,0);
