async function makeInitial():Promise<Profile>{
 const now=Date.now();let value:Profile;
 if(scenario==='rich')value=makeRichProfile(now);else if(scenario==='import-busy')value=makeInFlightLegacy(now);else value=parseProfile(initialProfile(now));
 return parseProfile(value);
}
async function main():Promise<void>{
 try{
  fs.mkdirSync(profileRoot,{recursive:true,mode:0o700});fs.mkdirSync(evidenceDir,{recursive:true});fs.mkdirSync(workEvidenceDir,{recursive:true});fs.chmodSync(profileRoot,0o700);markIsolatedFolder(profileRoot,app.getPath('appData'));
  preflight=await makeInitial();assert.equal(preflight.version,8);fs.mkdirSync(path.dirname(profileFile),{recursive:true,mode:0o700});fs.writeFileSync(profileFile,JSON.stringify(preflight)+'\n',{flag:'wx',mode:0o600});assert.deepEqual(parseProfile(JSON.parse(fs.readFileSync(profileFile,'utf8'))),preflight,'initial isolated profile parseProfile preflight');
  check('profile generated below marked /private/tmp root and parseProfile preflight passed',{profileRoot,profileFile,marker:path.join(profileRoot,'.pixelstreet-isolated-profile.json'),version:preflight.version,sequence:preflight.sequence,campPresent:Object.hasOwn(preflight,'camp'),profile:preflight.job});
  app.on('browser-window-created',(_event,win)=>track(win));shell=await startDesktop(profileRoot,true);await until(()=>shell?.game.state.status==='ready'&&!!shell.game.state.profile,'game worker ready');for(const win of BrowserWindow.getAllWindows())track(win);
  assert.equal(profile().sequence,preflight.sequence);check('real app main process and GameWorker loaded only isolated preflight profile',{sequence:profile().sequence,job:profile().job,coins:profile().coins,campPresent:Object.hasOwn(profile(),'camp')});
  if(scenario==='smoke')await smokeScenario();else if(scenario==='fresh')await freshScenario();else if(scenario==='rich')await richScenario();else if(scenario==='import')await importScenario();else await importBusyScenario();
  if(shell?.popupWindow&&!shell.popupWindow.isDestroyed()&&shell.popupWindow.isVisible())assert.fail('popup visible');if(shell)await shell.game.request('flush');
  if(scenario!=='import-busy')assert.deepEqual(new GameStore(path.dirname(profileFile)).value,profile(),'only the isolated profile persists through close/reopen store check');
  await readErrorsAndKeyboard();assert.equal(errors.length,0,`renderer console errors: ${errors.join('; ')}`);assert.equal(suppression.globalShortcut??0,0,'globalShortcut must never be registered');
  const finalWindows=snapshots();for(const row of finalWindows){assert.equal(row.isVisible,false,`native window ever visible: ${JSON.stringify(row)}`);assert.equal(row.isFocused,false,`native window ever focused: ${JSON.stringify(row)}`);}
  assert.deepEqual(hashesAtStart,productHashes(),'product files changed during hidden native acceptance');
  if(explicitFailureCount)status='FAIL';else status='PASS';check('hidden native run finished with original observations intact',{nativeWindows:finalWindows,suppression,explicitFailureCount,screenshotFiles,profileFile});
 }catch(error){status='FAIL';errors.push(String(error));checks.push({name:'scenario aborted on assertion/fixture error',status:'FAIL',detail:String(error)});console.error(error instanceof Error?error.stack:String(error));}
 finally{try{report(status==='FAIL'?new Error(errors.at(-1)||`${explicitFailureCount} explicit RED observations`):undefined);}catch(error){console.error(`report write failed: ${String(error)}`);}app.quit();}
}
